import React from "react";
import { createRoot } from "react-dom/client";
import { CMP } from "./CMP";

const elem = document.getElementById("cmp-root");
if (elem) {
  const root = createRoot(elem);
  root.render(<CMP />);
} else {
  console.error(
    "Could not mount App because #cmp-root was nowhere to be found",
  );
}
